from mkgen import *
T=[]; A=lambda *x,**k: a(T,*x,**k)
A("Найдите пропущенное число в последовательности: 3, 7, 15, x, 63, 127.","Тізбектегі жетіспейтін санды табыңыз: 3, 7, 15, x, 63, 127.",["29","31","47","59"],"B","Каждый член: предыдущий·2 + 1. 15·2 + 1 = 31; 31·2 + 1 = 63.")
A("В коробке 50 конфет. Из них 28 с нугой, 30 с орехами, 12 и с нугой, и с орехами, а остальные без начинки. Сколько конфет без начинки?","Қорапта 50 кәмпит бар. Олардың 28-і нугамен, 30-ы жаңғақпен, 12-сі нугамен де, жаңғақпен де, ал қалғаны толтырмасыз. Толтырмасыз қанша кәмпит бар?",["7","4","3","10"],"B","28 + 30 − 12 = 46 с начинкой; 50 − 46 = 4.")
A(r"Вычислите: \(\dfrac{245\cdot444-444\cdot242}{111\cdot67-70\cdot111}\).",r"Есептеңіз: \(\dfrac{245\cdot444-444\cdot242}{111\cdot67-70\cdot111}\).",["54","−3","−4","9"],"C","Числитель 444·3 = 1332; знаменатель 111·(67 − 70) = −333; 1332 : (−333) = −4.")
A("Из двух небольших городов навстречу друг другу в 12:30 выехали на велосипедах два друга со скоростями 12 км/ч и 18 км/ч. В дороге каждый из них отдыхал по 30 минут, и в 15:00 они встретились. Найдите расстояние между городами.","Екі шағын қаладан бір-біріне қарсы 12:30-да екі дос велосипедпен шықты, жылдамдықтары 12 км/сағ және 18 км/сағ. Жолда әрқайсысы 30 минуттан демалды, ал 15:00-де олар кездесті. Қалалар арасын табыңыз.",["84,5 км","92 км","60 км","65 км"],"C","В пути 2,5 − 0,5 = 2 часа. (12 + 18)·2 = 60 км.")
A(r"Али купил книгу и в первый день прочитал \(\tfrac25\) всей книги. Во второй день он прочитал \(\tfrac14\) остатка. Если за 2 дня он прочитал 220 страниц, сколько всего страниц в книге?",r"Әли кітап сатып алып, бірінші күні кітаптың \(\tfrac25\) бөлігін оқыды. Екінші күні қалғанының \(\tfrac14\) бөлігін оқыды. 2 күнде 220 бет оқыса, кітапта барлығы неше бет бар?",["560","380","400","480"],"C","2/5 + 3/5·1/4 = 2/5 + 3/20 = 11/20; 220 : 11/20 = 400.")
A(r"Найдите сумму всех натуральных решений неравенства \(\dfrac{2x-1}5<3\).",r"\(\dfrac{2x-1}5<3\) теңсіздігінің барлық натурал шешімдерінің қосындысын табыңыз.",["10","28","21","36"],"B","2x − 1 < 15, x < 8; решения 1…7, сумма 28.")
A("Из двух пунктов A и B на расстоянии 270 км одновременно в одном направлении выехали 2 машины, отношение скоростей которых 5 к 4. Более быстрая машина за первые 3 часа проехала 450 км. Сколько времени ещё понадобится, чтобы догнать вторую машину?","Арақашықтығы 270 км A және B пункттерінен бір бағытта 2 көлік бір мезгілде шықты, жылдамдықтарының қатынасы 5 пен 4. Жылдамырақ көлік алғашқы 3 сағатта 450 км жүрді. Екінші көлікті қуып жету үшін тағы қанша уақыт керек?",["5 ч","6 ч","3,5 ч","2 ч"],"B","Скорости 150 и 120 км/ч, сближение 30 км/ч; 270 : 30 = 9 ч; ещё 9 − 3 = 6 ч.",ok=["5 сағ","6 сағ","3,5 сағ","2 сағ"])
A("Найдите разницу периметров: прямоугольника со сторонами 14 дм и 6 дм и квадрата со стороной 5 дм.","Қабырғалары 14 дм және 6 дм тіктөртбұрыштың және қабырғасы 5 дм шаршының периметрлерінің айырмасын табыңыз.",["20 дм","18 дм","46 дм","16 дм"],"A","40 − 20 = 20 дм.")
A("Площадь футбольного стадиона 36 000 м². На карте масштаба 1 : 5000 длина стадиона равна 6 см. Какова реальная ширина стадиона?","Футбол стадионының ауданы 36 000 м². Масштабы 1 : 5000 картада стадионның ұзындығы 6 см. Стадионның нақты ені қандай?",["2,5 см","120 м","300 м","200 м"],"B","Длина 6·5000 = 30 000 см = 300 м; ширина 36 000 : 300 = 120 м.")
A(r"Найдите число, противоположное корню уравнения \(-3{,}2x-2{,}5(-2{,}4x+3)-\tfrac12=-22\).",r"\(-3{,}2x-2{,}5(-2{,}4x+3)-\tfrac12=-22\) теңдеуінің түбіріне қарама-қарсы санды табыңыз.",["14","10","5","−5"],"C","−3,2x + 6x − 7,5 − 0,5 = −22 → 2,8x = −14 → x = −5; противоположное 5.")
A("Найдите площадь квадрата, повёрнутого на клетчатой бумаге так, что его диагональ равна 6 клеткам, если сторона одной клетки 3 см.","Торлы қағазда диагоналі 6 торға тең болатындай бұрылған шаршының ауданын табыңыз, бір тордың қабырғасы 3 см.",["81 см²","108 см²","162 см²","324 см²"],"C","Диагональ 18 см; S = d²/2 = 324/2 = 162 см².")
A("Найдите концентрацию содового раствора, полученного смешиванием раствора массой 600 г с концентрацией соды 40% и второго раствора массой 1400 г с концентрацией 15%.","Массасы 600 г, концентрациясы 40% ерітіндіні массасы 1400 г, концентрациясы 15% екінші ерітіндімен араластырып алынған сода ерітіндісінің концентрациясын табыңыз.",["22%","22,5%","18%","25%"],"B","240 + 210 = 450 г соды в 2000 г: 22,5%.")
A(r"Найдите произведение корней уравнения \(2|-2y-5|-9=9{,}6:3{,}2\).",r"\(2|-2y-5|-9=9{,}6:3{,}2\) теңдеуінің түбірлерінің көбейтіндісін табыңыз.",["2,75","−2,75","−0,5",r"\(-\tfrac94\)"],"B","|−2y − 5| = 6: y = −5,5 или y = 0,5; произведение −2,75.")
A("Найдите произведение числа, обратного 4, и числа, противоположного −6.","4 санына кері сан мен −6 санына қарама-қарсы санның көбейтіндісін табыңыз.",["0,8","1,5","−6","0,4"],"B","(1/4)·6 = 1,5.")
A("Когда Абылай зашёл в автобус, там было 30 пассажиров вместе с ним. На следующей остановке вышли 4, а зашли 9 человек. Если на следующей остановке Абылай и ещё 10 пассажиров вышли, а 6 человек зашли, сколько стало пассажиров в автобусе?","Әбілай автобусқа кіргенде, онымен бірге 30 жолаушы болды. Келесі аялдамада 4 адам түсіп, 9 адам кірді. Келесі аялдамада Әбілай және тағы 10 жолаушы түсіп, 6 адам кірсе, автобуста қанша жолаушы қалды?",["29","30","31","32"],"B","30 − 4 + 9 = 35; 35 − 11 + 6 = 30.")
A("Велосипедист, собака и бегун делают круг вокруг стадиона за 3, 4 и 6 минут соответственно. Найдите отношение их скоростей.","Велосипедші, ит және жүгіруші стадионды 3, 4 және 6 минутта бір айналады. Олардың жылдамдықтарының қатынасын табыңыз.",["15 : 12 : 10","4 : 3 : 2","6 : 8 : 9","3 : 4 : 6"],"B","Скорости обратно пропорциональны времени: 1/3 : 1/4 : 1/6 = 4 : 3 : 2.")
A(r"Найдите, сколько чисел здесь суммируется: \(25+26+27+\ldots+140\).",r"Мұнда қанша сан қосылғанын табыңыз: \(25+26+27+\ldots+140\).",["111","113","116","115"],"C","140 − 25 + 1 = 116.")
A("Длина отрезка AB на координатной прямой составляет 12,55 единичных отрезка. Начальная точка A(−5,29), точка B правее точки A. Найдите координату точки B.","Координаталық түзудегі AB кесіндісінің ұзындығы 12,55 бірлік кесінді. Бастапқы нүкте A(−5,29), B нүктесі A-дан оңға қарай орналасқан. B нүктесінің координатасын табыңыз.",["17,84","7,26","7,34","−7,26"],"B","−5,29 + 12,55 = 7,26.")
A("Если от числа 2022 отнимать число k 37 раз, то получится 24. Найдите число k.","2022 санынан k санын 37 рет азайтса, 24 шығады. k санын табыңыз.",["49","54","59","81"],"B","2022 − 37k = 24, 37k = 1998, k = 54.")
A("На схеме показаны дети из 3А класса: девочки составляют 35%, мальчики — 65%; из мальчиков 40% учатся на «3» и «4». Сколько процентов составляют мальчики, которые учатся на «3» и «4», от всего класса?","Сызбада 3А сыныбының балалары көрсетілген: қыздар 35%, ұлдар 65%; ұлдардың 40%-ы «3» және «4»-ке оқиды. «3» және «4»-ке оқитын ұлдар бүкіл сыныптың неше пайызын құрайды?",["42%","54%","26%","34%"],"C","0,65·0,4 = 0,26 = 26%.")
A(r"Расставьте числа по убыванию: \(a=-0{,}56;\ b=\tfrac59;\ c=-\tfrac6{11};\ d=-0{,}(48);\ e=0{,}58\).",r"Сандарды кему ретімен орналастырыңыз: \(a=-0{,}56;\ b=\tfrac59;\ c=-\tfrac6{11};\ d=-0{,}(48);\ e=0{,}58\).",["a, d, c, e, b","e, b, c, d, a","e, b, d, c, a","b, e, d, c, a"],"C","e = 0,58; b ≈ 0,556; d ≈ −0,485; c ≈ −0,545; a = −0,56.")
A("В баскетбольном матче между клубами Астана и ЦСКА отношение очков только в первом тайме 5 : 3, во втором тайме 4 : 3, причём Астана набрала столько же очков, сколько в первом тайме, а ЦСКА набрал на 6 очков больше, чем в первом тайме. Найдите счёт после двух таймов.","Астана мен ЦСКА клубтары арасындағы баскетбол матчында бірінші таймдағы ұпайлар қатынасы 5 : 3, екінші таймда 4 : 3, Астана бірінші таймдағыдай ұпай жинады, ал ЦСКА бірінші таймға қарағанда 6 ұпай артық жинады. Екі таймнан кейінгі есепті табыңыз.",["80 : 54","75 : 60","70 : 50","64 : 48"],"A","Астана 5k = 4m, ЦСКА 3m = 3k + 6 → k = 8, m = 10. Астана 40 + 40 = 80; ЦСКА 24 + 30 = 54.")
A(r"Если \(\angle AOC\) составляет \(\tfrac13\) части от \(\angle AOD\) (прямой угол), то найдите, чему равен \(\angle DOE\) (точки \(C,O,E\) лежат на одной прямой).",r"\(\angle AOC\) бұрышы \(\angle AOD\) (тік бұрыш) бұрышының \(\tfrac13\) бөлігін құраса, \(\angle DOE\) бұрышы неге тең екенін табыңыз (\(C,O,E\) нүктелері бір түзуде жатыр).",["30°","45°","60°","35°"],"C","∠AOC = 30°; ∠BOC = 90° − 30° = 60°; ∠DOE вертикален ∠BOC, поэтому 60°.")
A("У Аружан есть 900 тг, и она хочет купить на них тетради и ручки. Если она купит 5 ручек и 2 тетради, то у неё останется 50 тг, а если 3 ручки и 2 тетради, то останется 190 тг. Сколько стоит 1 тетрадь?","Аружанда 900 тг бар, ол соған дәптер мен қалам сатып алғысы келеді. Егер 5 қалам мен 2 дәптер алса, 50 тг қалады, ал 3 қалам мен 2 дәптер алса, 190 тг қалады. 1 дәптер қанша тұрады?",["120 тг","60 тг","250 тг","170 тг"],"C","2 ручки стоят 140, ручка 70. 2 тетради = 850 − 350 = 500, одна 250.")
A("У Асанали есть 6 палочек по 30 см. Он хочет распилить их так, чтобы было 36 палочек по 5 см. Сколько распилов нужно сделать?","Асаналиде ұзындығы 30 см 6 таяқша бар. Ол оларды 5 см 36 таяқша болатындай етіп кеспекші. Қанша рет кесу керек?",["24","18","30","36"],"C","Каждую палочку на 6 частей — 5 распилов; 6·5 = 30.")
A("4 кошки съедают 80 ложек корма за 5 дней. За сколько дней 6 кошек съедят 72 ложки корма?","4 мысық 80 қасық жемді 5 күнде жейді. 6 мысық 72 қасық жемді қанша күнде жейді?",["1 день","8 дней","3 дня","2 дня"],"C","Одна кошка в день 80 : 20 = 4 ложки. 72 : (6·4) = 3 дня.",ok=["1 күн","8 күн","3 күн","2 күн"])
A(r"Найдите \(y:x\), если \(\dfrac3{4x}=\dfrac6{2y}\).",r"\(\dfrac3{4x}=\dfrac6{2y}\) болса, \(y:x\) табыңыз.",["2","4","0,5",r"\(\tfrac15\)"],"B","3·2y = 6·4x → 6y = 24x → y/x = 4.")
A("Максимальная скорость мотоцикла 600 дм/с, а лёгковой машины 300 000 000 мм/ч. Найдите разницу этих скоростей.","Мотоциклдің ең жоғары жылдамдығы 600 дм/с, жеңіл көліктікі 300 000 000 мм/сағ. Осы жылдамдықтардың айырмасын табыңыз.",["84 км/ч","70 км/ч","200 км/ч","180 км/ч"],"A","600 дм/с = 60 м/с = 216 км/ч; 300 000 000 мм/ч = 300 км/ч; разница 84 км/ч.",ok=["84 км/сағ","70 км/сағ","200 км/сағ","180 км/сағ"])
A("У скольких трёхзначных натуральных чисел первая цифра 7, а последняя 5?","Неше үш таңбалы натурал санның бірінші цифры 7, ал соңғы цифры 5?",["9","10","100","90"],"B","Средняя цифра любая от 0 до 9 — 10 чисел.")
A("Найдите периметр фигуры — круга радиусом 10 см с вырезанным сектором в четверть круга (число π ≈ 3,14).","Фигураның периметрін табыңыз — радиусы 10 см, төрттен бір бөлігі секторы қиылған дөңгелек (π ≈ 3,14).",["47,1 см","67,1 см","62,8 см","30 см"],"B","Дуга 3/4·2·3,14·10 = 47,1; два радиуса 20; сумма 67,1 см.")
A("8 труб могут наполнить бассейн за 1 час 20 минут. Если включить ещё 4 трубы с такой же производительностью (всего 12 труб), то за какое время наполнится бассейн?","8 құбыр бассейнді 1 сағат 20 минутта толтыра алады. Дәл сондай өнімділікпен тағы 4 құбыр қосса (барлығы 12 құбыр), бассейн қанша уақытта толтырылады?",["1 ч 22 мин","40 мин","53 мин 20 с","35 мин"],"C","8·80 = 640 труб-минут; 640 : 12 = 53 1/3 мин = 53 мин 20 с.")
A("Вычислите: \\(-8-(-(-(-3+(-7))))\\).","Есептеңіз: \\(-8-(-(-(-3+(-7))))\\).",["−18","−12","2","8"],"C","−3 + (−7) = −10; −(−10) = 10; −10; −8 − (−10) = 2.")
A("Нападающий за сезон 2014-2015 забил 25 голов, а за весь следующий сезон 2015-2016 забил 32 гола. Сколько процентов составляют забитые им голы в сезоне 2015-2016 от голов сезона 2014-2015?","Шабуылшы 2014-2015 маусымында 25 гол соқты, ал келесі 2015-2016 маусымында 32 гол соқты. 2015-2016 маусымындағы голдар 2014-2015 маусымындағы голдардың неше пайызын құрайды?",["129","128","78","128,5"],"B","32 : 25 = 1,28 = 128%.")
A(r"Решите неравенство: \(\dfrac{3+y}2-\dfrac{y+1}7<y+2\).",r"Теңсіздікті шешіңіз: \(\dfrac{3+y}2-\dfrac{y+1}7<y+2\).",[r"\([-1;+\infty)\)",r"\((-\infty;-1]\)",r"\((-1;+\infty)\)",r"\((-\infty;-1)\)"],"C","Умножим на 14: 21 + 7y − 2y − 2 < 14y + 28 → −9 < 9y → y > −1.")
A("Найдите градусную меру угла, равного 0,45 развёрнутого угла.","Жазыңқы бұрыштың 0,45 бөлігіне тең бұрыштың градустық өлшемін табыңыз.",["60°","81°","45°","90°"],"B","180°·0,45 = 81°.")
A("Цена футболки 2500 тг. Её повысили на 20%, а затем понизили на 20%. Сколько стала стоить футболка?","Футболканың бағасы 2500 тг. Оны 20%-ға көтеріп, содан кейін 20%-ға төмендетті. Футболка қанша тұрады?",["2500 тг","2400 тг","3000 тг","2000 тг"],"B","2500·1,2·0,8 = 2400.")
A("7 тетрадей стоят 1050 тг. Сколько стоят 12 таких тетрадей?","7 дәптер 1050 тг тұрады. Осындай 12 дәптер қанша тұрады?",["1500 тг","1800 тг","1750 тг","2100 тг"],"B","Одна тетрадь 150 тг; 12·150 = 1800.")
A("Периметр квадрата равен 36 см. Найдите его площадь.","Шаршының периметрі 36 см. Оның ауданын табыңыз.",["9 см²","36 см²","81 см²","72 см²"],"C","Сторона 9 см, площадь 81 см².")
A("Среднее арифметическое шести чисел равно 15. Когда одно число убрали, среднее арифметическое оставшихся пяти стало равно 14. Найдите убранное число.","Алты санның орта арифметикалық мәні 15. Бір санды алып тастағанда, қалған бестің орта арифметикалық мәні 14 болды. Алынып тасталған санды табыңыз.",["16","18","20","25"],"C","6·15 = 90; 5·14 = 70; 90 − 70 = 20.")
A("Поезд длиной 200 м проходит мост длиной 400 м со скоростью 20 м/с. За какое время поезд пройдёт мост полностью?","Ұзындығы 200 м пойыз ұзындығы 400 м көпірден 20 м/с жылдамдықпен өтеді. Пойыз көпірден толық қанша уақытта өтеді?",["20 с","30 с","40 с","10 с"],"B","(200 + 400) : 20 = 30 с.")
write(T,"T06_MATH","t06-math.ts","Тест 6 · Математика")
